'use strict';
/*
 * Barphil Concept — Configurateur (version fichier unique)
 * Aucune dependance externe. Node 22+ requis (utilise node:sqlite).
 * Demarrage : node server.js
 */

const http = require('http');
const path = require('path');
const fs = require('fs');
const { DatabaseSync } = require('node:sqlite');

const PORT = process.env.PORT || 4321;
const ADMIN_KEY = process.env.ADMIN_KEY || 'barphil-admin';

// ---------------------------------------------------------------------
// Frontend assets (encodes en base64 pour eviter tout probleme
// d'echappement dans ce fichier unique)
// ---------------------------------------------------------------------
const ASSETS = {
  '/admin.html': { type: 'text/html; charset=utf-8', b64: '' },
  '/favicon.svg': { type: 'image/svg+xml', b64: '' },
  '/index.html': { type: 'text/html; charset=utf-8', b64: '' },
  '/styles.css': { type: 'text/css; charset=utf-8', b64: '' },
  '/app.js': { type: 'application/javascript; charset=utf-8', b64: '' },
};
function decodeAsset(a) { return Buffer.from(a.b64, 'base64'); }

// ---------------------------------------------------------------------
// Pricing / metre — source unique de verite
// ---------------------------------------------------------------------
const RATE_DEUX = 1400;
// Repartition gros/second issue de la ventilation reelle du projet DAFFADA
// (Repartition Materiaux Main-d'Oeuvre Marge - DAFFADA.pdf, lots 2 a 5 vs lots 6 a 12,
// hors fondations et hors maitrise d'oeuvre) : ~64% / ~36%.
const RATES = { deux: RATE_DEUX, gros: 900, second: 500 };
const PROFILE_PRICE_TAGS = {
  autoconstructeur: 'Tarif autoconstruction',
  artisan: 'Tarif professionnel partenaire',
  client: 'Tarif cle en main',
};
const SUPERVISEUR_FORFAIT = 900;
const SURFACE_MIN = 20;
const SURFACE_MAX = 500;

function isValidSurface(n) {
  return Number.isFinite(n) && n >= SURFACE_MIN && n <= SURFACE_MAX;
}

// Validation minimale des champs texte soumis par le client (email/longueurs).
// Le formulaire cote client valide deja ces champs, mais l'API doit rester
// robuste face a un appel direct (curl/fetch) qui contournerait le formulaire.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function isValidEmail(s) {
  return typeof s === 'string' && s.length <= 200 && EMAIL_RE.test(s);
}
const FIELD_MAX = { short: 200, message: 2000 };
function isValidLength(s, kind = 'short') {
  return s == null || (typeof s === 'string' && s.length <= FIELD_MAX[kind]);
}

function metreRows(travaux, surface) {
  const emprise = Math.round(surface * 1.12);
  const murs = Math.round(surface * 0.56);
  const toiture = Math.round(surface * 1.2);
  const cloisons = Math.round(surface * 0.9);
  const menuiseries = Math.max(6, Math.round(surface / 14));
  const isolation = Math.round(surface * 1.05);

  if (travaux === 'gros') {
    return [
      { label: 'Surface habitable', value: `${surface} m²` },
      { label: 'Emprise au sol', value: `${emprise} m²` },
      { label: 'Lineaire murs porteurs', value: `${murs} ml` },
      { label: 'Surface de toiture', value: `${toiture} m²` },
    ];
  }
  if (travaux === 'second') {
    return [
      { label: 'Surface habitable', value: `${surface} m²` },
      { label: 'Surface de cloisons', value: `${cloisons} m²` },
      { label: 'Menuiseries (portes/fenetres)', value: `${menuiseries} unites` },
      { label: 'Surface a isoler', value: `${isolation} m²` },
    ];
  }
  return [
    { label: 'Surface habitable', value: `${surface} m²` },
    { label: 'Emprise au sol', value: `${emprise} m²` },
    { label: 'Lineaire murs porteurs', value: `${murs} ml` },
    { label: 'Surface de toiture', value: `${toiture} m²` },
    { label: 'Surface de cloisons', value: `${cloisons} m²` },
    { label: 'Menuiseries (portes/fenetres)', value: `${menuiseries} unites` },
  ];
}

// Ventilation reelle (hors fondations, hors alea) du projet DAFFADA :
// materiaux 46,0% / main-d'oeuvre pose 41,0% / coordination et suivi 13,0%.
// Source : Repartition Materiaux Main-d'Oeuvre Marge - DAFFADA.pdf (31/08/2026).
const DEVIS_SPLIT = { materiaux: 0.46, poseMainOeuvre: 0.41, coordination: 0.13 };

function computeDevis({ profil, travaux, surface, superviseur }) {
  const rate = RATES[travaux] ?? RATE_DEUX;
  const base = rate * surface;
  const materiaux = Math.round(base * DEVIS_SPLIT.materiaux);

  // Profil "artisan" : l'artisan partenaire assure lui-meme la pose et le
  // suivi de son chantier avec ses propres equipes. Barphil ne lui fournit
  // que les materiaux/elements de structure : la pose et la coordination
  // de chantier (qui n'ont pas lieu d'etre facturees par Barphil dans ce
  // cas) sont donc exclues de son estimation.
  if (profil === 'artisan') {
    return {
      rate,
      priceTag: PROFILE_PRICE_TAGS.artisan,
      breakdown: [
        { label: 'Materiaux et elements de structure', amount: materiaux },
      ],
      total: materiaux,
      note: "Estimation du cout des materiaux fournis par Barphil pour un chantier realise par vos propres equipes. Pose, main-d'oeuvre et suivi de chantier ne sont pas inclus.",
    };
  }

  const poseMainOeuvre = Math.round(base * DEVIS_SPLIT.poseMainOeuvre);
  const coordination = base - materiaux - poseMainOeuvre;
  const superviseurCost = profil === 'autoconstructeur' && superviseur ? SUPERVISEUR_FORFAIT : 0;
  const total = materiaux + poseMainOeuvre + coordination + superviseurCost;
  return {
    rate,
    priceTag: PROFILE_PRICE_TAGS[profil] || PROFILE_PRICE_TAGS.client,
    breakdown: [
      { label: 'Materiaux et fournitures', amount: materiaux },
      { label: 'Pose et main-d\'oeuvre', amount: poseMainOeuvre },
      { label: 'Coordination et suivi de chantier', amount: coordination },
      ...(superviseurCost ? [{ label: 'Accompagnement superviseur', amount: superviseurCost, addon: true }] : []),
    ],
    total,
    note: "Le cout des fondations n'est pas inclus dans cette estimation.",
  };
}

// ---------------------------------------------------------------------
// Inspection PDF (sans dependance) — nb de pages + format papier reel
// ---------------------------------------------------------------------
const STANDARD_FORMATS = [
  { name: 'A4', w: 595, h: 842 },
  { name: 'A3', w: 842, h: 1191 },
  { name: 'A2', w: 1191, h: 1684 },
  { name: 'A1', w: 1684, h: 2384 },
  { name: 'A0', w: 2384, h: 3370 },
];
const FORMAT_SURFACE_FACTOR = { A4: 0.8, A3: 1.0, A2: 1.3, A1: 1.6, A0: 2.0, Inconnu: 1.0 };

function detectFormat(widthPt, heightPt) {
  const w = Math.max(widthPt, heightPt);
  const h = Math.min(widthPt, heightPt);
  let best = null, bestDelta = Infinity;
  for (const f of STANDARD_FORMATS) {
    const fw = Math.max(f.w, f.h), fh = Math.min(f.w, f.h);
    const delta = Math.abs(fw - w) + Math.abs(fh - h);
    if (delta < bestDelta) { bestDelta = delta; best = f.name; }
  }
  return bestDelta < 40 ? best : 'Inconnu';
}

function inspectPdfBuffer(buffer) {
  const text = buffer.toString('latin1');
  const pageMatches = text.match(/\/Type\s*\/Page(?!s)/g) || [];
  const pageCount = pageMatches.length || 1;
  const mediaBoxMatch = text.match(/\/MediaBox\s*\[\s*(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s*\]/);
  let format = 'Inconnu';
  if (mediaBoxMatch) {
    const [, x1, y1, x2, y2] = mediaBoxMatch.map(Number);
    format = detectFormat(Math.abs(x2 - x1), Math.abs(y2 - y1));
  }
  return { pageCount, format, sizeBytes: buffer.length };
}

function suggestSurface(filesInfo) {
  const totalPages = filesInfo.reduce((sum, f) => sum + f.pageCount, 0) || 1;
  const dominantFormat = filesInfo[0]?.format || 'Inconnu';
  const factor = FORMAT_SURFACE_FACTOR[dominantFormat] ?? 1.0;
  const raw = totalPages * 55 * factor;
  return Math.min(400, Math.max(40, Math.round(raw / 5) * 5));
}

// ---------------------------------------------------------------------
// Parseur multipart/form-data minimal (upload de fichiers)
// ---------------------------------------------------------------------
function parseMultipart(buffer, contentType) {
  const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/.exec(contentType || '');
  if (!boundaryMatch) return { fields: {}, files: [] };
  const boundary = '--' + (boundaryMatch[1] || boundaryMatch[2]).trim();
  const boundaryBuf = Buffer.from(boundary);

  const parts = [];
  let start = buffer.indexOf(boundaryBuf);
  while (start !== -1) {
    const next = buffer.indexOf(boundaryBuf, start + boundaryBuf.length);
    if (next === -1) break;
    let chunk = buffer.slice(start + boundaryBuf.length, next);
    if (chunk.slice(0, 2).toString() === '--') break;
    if (chunk.slice(0, 2).toString('latin1') === '\r\n') chunk = chunk.slice(2);
    if (chunk.slice(-2).toString('latin1') === '\r\n') chunk = chunk.slice(0, -2);
    parts.push(chunk);
    start = next;
  }

  const fields = {}; const files = [];
  for (const part of parts) {
    const headerEnd = part.indexOf('\r\n\r\n');
    if (headerEnd === -1) continue;
    const rawHeaders = part.slice(0, headerEnd).toString('latin1');
    const body = part.slice(headerEnd + 4);
    const nameMatch = /name="([^"]+)"/.exec(rawHeaders);
    const filenameMatch = /filename="([^"]*)"/.exec(rawHeaders);
    const ctMatch = /Content-Type:\s*([^\r\n]+)/i.exec(rawHeaders);
    const name = nameMatch ? nameMatch[1] : null;
    if (!name) continue;
    if (filenameMatch && filenameMatch[1]) {
      files.push({ field: name, filename: filenameMatch[1], contentType: ctMatch ? ctMatch[1].trim() : 'application/octet-stream', buffer: body });
    } else {
      fields[name] = body.toString('utf8');
    }
  }
  return { fields, files };
}

// ---------------------------------------------------------------------
// Persistance SQLite (module natif node:sqlite)
// ATTENTION DEPLOIEMENT : sur Render (plan standard, sans disque persistant),
// ce fichier est perdu a chaque redeploiement/redemarrage. Attacher un
// "Persistent Disk" monte sur ce dossier ./data avant de collecter de vraies
// demandes clients, sous peine de perdre les leads.
// ---------------------------------------------------------------------
const DATA_DIR = path.join(__dirname, 'data');
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
const db = new DatabaseSync(path.join(DATA_DIR, 'barphil.db'));
db.exec(`
  CREATE TABLE IF NOT EXISTS leads (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    nom TEXT NOT NULL,
    email TEXT NOT NULL,
    telephone TEXT,
    region TEXT,
    profil TEXT NOT NULL,
    travaux TEXT NOT NULL,
    surface INTEGER NOT NULL,
    superviseur INTEGER NOT NULL DEFAULT 0,
    total_estime INTEGER NOT NULL,
    fichiers TEXT
  )
`);
// Ajout retro-compatible de la colonne region si la base existait deja sans elle.
try { db.exec('ALTER TABLE leads ADD COLUMN region TEXT'); } catch { /* colonne deja presente */ }

// Partenaires regionaux (artisans/constructeurs qui rejoignent le reseau Barphil).
// Les clients qui candidatent depuis une region couverte par un partenaire lui
// sont ensuite orientes par l'equipe Barphil (mise en relation manuelle a ce stade).
db.exec(`
  CREATE TABLE IF NOT EXISTS partners (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    entreprise TEXT NOT NULL,
    siret TEXT,
    region TEXT NOT NULL,
    nom TEXT NOT NULL,
    email TEXT NOT NULL,
    telephone TEXT,
    message TEXT
  )
`);

function insertLead(lead) {
  const stmt = db.prepare(`INSERT INTO leads (created_at, nom, email, telephone, region, profil, travaux, surface, superviseur, total_estime, fichiers)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
  const info = stmt.run(new Date().toISOString(), lead.nom, lead.email, lead.telephone || '', lead.region || '', lead.profil, lead.travaux, lead.surface, lead.superviseur ? 1 : 0, lead.total, JSON.stringify(lead.fichiers || []));
  return Number(info.lastInsertRowid);
}
function listLeads() {
  const rows = db.prepare('SELECT * FROM leads ORDER BY id DESC').all();
  return rows.map((r) => ({ ...r, fichiers: JSON.parse(r.fichiers || '[]'), superviseur: !!r.superviseur }));
}

function insertPartner(p) {
  const stmt = db.prepare(`INSERT INTO partners (created_at, entreprise, siret, region, nom, email, telephone, message)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)`);
  const info = stmt.run(new Date().toISOString(), p.entreprise, p.siret || '', p.region, p.nom, p.email, p.telephone || '', p.message || '');
  return Number(info.lastInsertRowid);
}
function listPartners() {
  return db.prepare('SELECT * FROM partners ORDER BY id DESC').all();
}

// ---------------------------------------------------------------------
// Serveur HTTP
// ---------------------------------------------------------------------
function send(res, status, body, headers = {}) {
  res.writeHead(status, { 'Access-Control-Allow-Origin': '*', ...headers });
  res.end(body);
}
function sendJson(res, status, obj) {
  send(res, status, JSON.stringify(obj), { 'Content-Type': 'application/json; charset=utf-8' });
}
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = []; let size = 0; const LIMIT = 25 * 1024 * 1024;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > LIMIT) { reject(new Error('PAYLOAD_TOO_LARGE')); req.destroy(); return; }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const { pathname } = url;

  try {
    if (req.method === 'OPTIONS') {
      return send(res, 204, '', { 'Access-Control-Allow-Methods': 'GET,POST,OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-Admin-Key' });
    }

    if (pathname === '/api/analyze-plans' && req.method === 'POST') {
      const raw = await readBody(req);
      const { files } = parseMultipart(raw, req.headers['content-type']);
      const pdfFiles = files.filter((f) => f.filename.toLowerCase().endsWith('.pdf'));
      if (!pdfFiles.length) return sendJson(res, 400, { error: 'Aucun fichier PDF recu.' });
      const filesInfo = pdfFiles.map((f) => ({ filename: f.filename, ...inspectPdfBuffer(f.buffer) }));
      return sendJson(res, 200, { files: filesInfo, suggestedSurface: suggestSurface(filesInfo) });
    }

    if (pathname === '/api/metre' && req.method === 'POST') {
      const raw = await readBody(req);
      const { travaux, surface } = JSON.parse(raw.toString('utf8') || '{}');
      const surfaceNum = Number(surface);
      if (!travaux || !surface) return sendJson(res, 400, { error: 'travaux et surface requis.' });
      if (!isValidSurface(surfaceNum)) return sendJson(res, 400, { error: `surface doit etre comprise entre ${SURFACE_MIN} et ${SURFACE_MAX} m².` });
      return sendJson(res, 200, { rows: metreRows(travaux, surfaceNum) });
    }

    if (pathname === '/api/devis' && req.method === 'POST') {
      const raw = await readBody(req);
      const { profil, travaux, surface, superviseur } = JSON.parse(raw.toString('utf8') || '{}');
      const surfaceNum = Number(surface);
      if (!profil || !travaux || !surface) return sendJson(res, 400, { error: 'profil, travaux et surface requis.' });
      if (!isValidSurface(surfaceNum)) return sendJson(res, 400, { error: `surface doit etre comprise entre ${SURFACE_MIN} et ${SURFACE_MAX} m².` });
      return sendJson(res, 200, computeDevis({ profil, travaux, surface: surfaceNum, superviseur: !!superviseur }));
    }

    if (pathname === '/api/leads' && req.method === 'POST') {
      const raw = await readBody(req);
      const lead = JSON.parse(raw.toString('utf8') || '{}');
      if (lead.website) {
        // Honeypot field filled -> likely a bot. Pretend success, save nothing.
        return sendJson(res, 201, { ok: true, id: 0, total: 0 });
      }
      const surfaceNum = Number(lead.surface);
      if (!lead.nom || !lead.email || !lead.profil || !lead.travaux || !lead.surface) return sendJson(res, 400, { error: 'Champs manquants.' });
      if (!isValidSurface(surfaceNum)) return sendJson(res, 400, { error: `surface doit etre comprise entre ${SURFACE_MIN} et ${SURFACE_MAX} m².` });
      if (!isValidEmail(lead.email)) return sendJson(res, 400, { error: 'Email invalide.' });
      if (!isValidLength(lead.nom) || !isValidLength(lead.telephone) || !isValidLength(lead.region)) {
        return sendJson(res, 400, { error: 'Un champ depasse la longueur autorisee.' });
      }
      const devis = computeDevis({ profil: lead.profil, travaux: lead.travaux, surface: surfaceNum, superviseur: !!lead.superviseur });
      const id = insertLead({ ...lead, total: devis.total });
      return sendJson(res, 201, { ok: true, id, total: devis.total });
    }

    if (pathname === '/api/leads' && req.method === 'GET') {
      if (req.headers['x-admin-key'] !== ADMIN_KEY) return sendJson(res, 401, { error: 'Non autorise.' });
      return sendJson(res, 200, { leads: listLeads() });
    }

    if (pathname === '/api/partners' && req.method === 'POST') {
      const raw = await readBody(req);
      const p = JSON.parse(raw.toString('utf8') || '{}');
      if (p.website) {
        // Honeypot field filled -> likely a bot. Pretend success, save nothing.
        return sendJson(res, 201, { ok: true, id: 0 });
      }
      if (!p.entreprise || !p.region || !p.nom || !p.email) return sendJson(res, 400, { error: 'Champs manquants.' });
      if (!isValidEmail(p.email)) return sendJson(res, 400, { error: 'Email invalide.' });
      if (!isValidLength(p.entreprise) || !isValidLength(p.siret) || !isValidLength(p.region) || !isValidLength(p.nom) || !isValidLength(p.telephone) || !isValidLength(p.message, 'message')) {
        return sendJson(res, 400, { error: 'Un champ depasse la longueur autorisee.' });
      }
      const id = insertPartner(p);
      return sendJson(res, 201, { ok: true, id });
    }

    if (pathname === '/api/partners' && req.method === 'GET') {
      if (req.headers['x-admin-key'] !== ADMIN_KEY) return sendJson(res, 401, { error: 'Non autorise.' });
      return sendJson(res, 200, { partners: listPartners() });
    }

    // ---- Real photos served from disk (./images/) ----
    if (pathname.startsWith('/images/') && req.method === 'GET') {
      const IMAGES_DIR = __dirname;
      const requested = path.normalize(decodeURIComponent(pathname.slice('/images/'.length)));
      if (requested.startsWith('..')) return send(res, 403, 'Forbidden');
      const filePath = path.join(IMAGES_DIR, requested);
      const relative = path.relative(IMAGES_DIR, filePath);
      if (relative.startsWith('..') || path.isAbsolute(relative)) return send(res, 403, 'Forbidden');
      const IMAGE_MIME = { '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png', '.webp': 'image/webp' };
      const ext = path.extname(filePath).toLowerCase();
      if (!IMAGE_MIME[ext]) return send(res, 404, 'Not found');
      try {
        const data = fs.readFileSync(filePath);
        return send(res, 200, data, { 'Content-Type': IMAGE_MIME[ext], 'Cache-Control': 'public, max-age=86400' });
      } catch {
        return send(res, 404, 'Image introuvable');
      }
    }

    if (req.method === 'GET') {
      const key = pathname === '/' ? '/index.html' : (pathname === '/admin' ? '/admin.html' : pathname);
      const asset = ASSETS[key];
      if (asset) return send(res, 200, decodeAsset(asset), { 'Content-Type': asset.type });
      return send(res, 404, 'Not found');
    }

    return sendJson(res, 404, { error: 'Route inconnue.' });
  } catch (err) {
    console.error(err);
    return sendJson(res, 500, { error: 'Erreur serveur.', detail: err.message });
  }
});

server.listen(PORT, () => {
  console.log(`Barphil configurateur — serveur demarre sur http://localhost:${PORT}`);
  if (!process.env.ADMIN_KEY) {
    console.warn('ATTENTION: ADMIN_KEY non definie, la valeur par defaut est utilisee. Definissez la variable d\'environnement ADMIN_KEY avant tout deploiement public.');
  }
  console.log(`Admin leads: GET /api/leads avec le header X-Admin-Key: ${ADMIN_KEY}`);
});
